    def motor_test_page(self, title, axis):
        page = self.card()
        l = QVBoxLayout(page)
        l.addWidget(self.section_title(title))
        value = QLabel('Richtungstest: 5 Grad pro Klick')
        value.setObjectName('bigStatus')
        l.addWidget(value)
        row = QHBoxLayout()
        minus = QPushButton('Rückwärts')
        plus = QPushButton('Vorwärts')
        stop = QPushButton('STOP')
        stop.setObjectName('danger')
        row.addWidget(minus)
        row.addWidget(stop)
        row.addWidget(plus)
        l.addLayout(row)
        minus.clicked.connect(lambda: self.move_axis(axis, -1, 5, test=True))
        plus.clicked.connect(lambda: self.move_axis(axis, +1, 5, test=True))
        stop.clicked.connect(self.stop_all)
        back = QPushButton('← Zur Komponentenauswahl')
        back.clicked.connect(lambda: self.test_stack.setCurrentIndex(0))
        l.addWidget(back)
        l.addStretch()
        return page

