    def apply_style(self):
        self.setStyleSheet('\n            QMainWindow, QWidget {\n                background: #0d1117;\n                color: #e7edf5;\n                font-family: "Segoe UI";\n                font-size: 14px;\n            }\n\n            QFrame#nav {\n                background: #111820;\n                border-right: 1px solid #243140;\n            }\n\n            QFrame#center {\n                background: #0d1117;\n            }\n\n            QFrame#rightpanel {\n                background: #111820;\n                border-left: 1px solid #243140;\n            }\n\n            QFrame#card {\n                background: #151d27;\n                border: 1px solid #263546;\n                border-radius: 14px;\n            }\n\n            QLabel#logo {\n                color: #65b7ff;\n                font-size: 25px;\n                font-weight: 800;\n                letter-spacing: 2px;\n            }\n\n            QLabel#h1 {\n                font-size: 26px;\n                font-weight: 800;\n                color: #f4f8fc;\n            }\n\n            QLabel#h2 {\n                font-size: 17px;\n                font-weight: 700;\n                color: #dfe9f5;\n            }\n\n            QLabel#muted {\n                color: #8fa1b4;\n            }\n\n            QLabel#bigStatus {\n                font-size: 22px;\n                font-weight: 800;\n                color: #ffffff;\n            }\n\n            QLabel#value {\n                font-size: 22px;\n                font-weight: 700;\n                color: #ffffff;\n            }\n\n            QLabel#accentAz {\n                color: #3aa6ff;\n                font-weight: 700;\n            }\n\n            QLabel#accentEl {\n                color: #ffb347;\n                font-weight: 700;\n            }\n\n            QLabel#successText {\n                color: #52d273;\n                font-weight: 700;\n            }\n\n            QLabel#dangerText {\n                color: #ff6b6b;\n                font-weight: 700;\n            }\n\n            QLabel#lcd {\n                background: #b7cf8d;\n                color: #1b2a13;\n                border: 4px solid #283327;\n                border-radius: 8px;\n                font-family: Consolas;\n                font-size: 20px;\n                font-weight: 700;\n                padding: 10px;\n            }\n\n            QPushButton {\n                background: #1b2734;\n                color: #eaf2fa;\n                border: 1px solid #31445a;\n                border-radius: 9px;\n                padding: 10px 14px;\n                font-weight: 600;\n            }\n\n            QPushButton:hover {\n                background: #25364a;\n                border-color: #4d6d8f;\n            }\n\n            QPushButton:pressed {\n                background: #101820;\n            }\n\n            QPushButton:checked {\n                background: #1d4d73;\n                border-color: #3aa6ff;\n                color: white;\n            }\n\n            QPushButton#primary {\n                background: #1769aa;\n                border-color: #318cd1;\n            }\n\n            QPushButton#success {\n                background: #1f7a43;\n                border-color: #39a960;\n            }\n\n            QPushButton#danger {\n                background: #8d2d35;\n                border-color: #c14b55;\n            }\n\n            QComboBox, QLineEdit, QDoubleSpinBox, QSpinBox {\n                background: #0f1620;\n                color: #edf4fb;\n                border: 1px solid #31445a;\n                border-radius: 8px;\n                padding: 8px;\n                min-height: 24px;\n            }\n\n            QRadioButton {\n                spacing: 7px;\n            }\n\n            QStatusBar {\n                background: #101720;\n                color: #9fb2c6;\n            }\n        ')
